<?php get_header(); while(have_posts()): the_post(); ?><main id="main" class="single-main site-shell"><header class="page-hero"><span class="eyebrow"><?php echo esc_html(get_the_date()); ?></span><h1><?php the_title(); ?></h1></header><article class="entry-content narrow"><?php if(has_post_thumbnail()) the_post_thumbnail('full'); the_content(); ?></article></main><?php endwhile; get_footer(); ?>